mapper.select:
select ifnull(MAX(sort), 0)
from pilipili.user_video_series
where user_id = #{userId};

mapper.update:
update pilipili.user_video_series

    series_name = #{seriesName}

        , series_description = #{seriesDescription}


        , update_time = #{updateTime}


